import re

# Test (\S+) in various contexts
patterns = [
    (r'(\S+) *\s*world', 'hello       world'),  # Left-align + 'world'
    (r'hello\s*(\S+)\s*', 'hello       world'), # Right-align + 'hello'  
    (r'hello\s*(.*?)\s*world', 'hello  there     world'), # Center-align
]

for p, s in patterns:
    m = re.match(p, s)
    if m:
        print(f"Pattern {p!r} on {s!r}: matched {m.group(1)!r}")
    else:
        m2 = re.search(p, s)
        if m2:
            print(f"Pattern {p!r} on {s!r}: searched, matched {m2.group(1)!r}")
        else:
            print(f"Pattern {p!r} on {s!r}: no match")
PYEOF
